q(1, 4, 'भारत में अनेकता में एकता का प्रतीक हिंदी है। कैसे?',
  'भारत में अनेक धर्म, जातियाँ, संस्कृतियाँ और अलग-अलग प्रांतों में अलग-अलग भाषाएँ हैं। फिर भी हिंदी देश के अधिकांश भागों में बोली और समझी जाती है। स्वतंत्रता संग्राम में देश को एक सूत्र में बाँधने का काम हिंदी ने किया; इसलिए वह अपने शाब्दिक अर्थ से भी ‘भारतीय’ भाषा है। संविधान ने उसे राजभाषा बनाया। उत्तर से दक्षिण, पूर्व से पश्चिम तक लोग हिंदी के माध्यम से एक-दूसरे से संपर्क करते हैं — इसलिए हिंदी अनेकता में एकता का प्रतीक है।')
for s, ins, op, k, ex in [('हिंदी भारतीयों की ‘साँसों’ में बसी भाषा है।', TS, ['श्वास', 'स्वाश', 'शेष'], 0, ''), ('भारत के अलग-अलग प्रांतों में अलग-अलग भाषा बोली जाती है।', KR, ['भारत', 'प्रांत', 'बोली जाती'], 2, ''),
                          ('उन्नीस सौ उनचास', SN, ['1957', '1947', '1949'], 2, ''), ('देश को एकता ……… सूत्र में बाँधने के लिए हिंदी की आवश्यकता है।', KC, ['का', 'के', 'की'], 1, ''),
                          ('हमें हिंदी सीखने का ‘संकल्प’ लेना है।', PR, ['निर्माण', 'सलाह', 'इच्छा'], 2, 'संकल्प = దృఢ నిశ్చయం/ఇచ్ఛ – ఎంపికల్లో దగ్గరైనది ‘इच्छा’.'),
                          ('भारत की ‘एकता’ सारे विश्व के लिए आदर्श है।', VL, ['वीरता', 'अनेकता', 'विवेकता'], 1, ''), ('भारत की ‘राजभाषा’ हिंदी है।', SM, ['द्वंद्व समास', 'द्विगु समास', 'तत्पुरुष समास'], 2, 'राज्य की भाषा – తత్పురుష.'),
                          ('भारतीय संविधान ने हिंदी को राजभाषा के रूप में ‘गौरवान्वित’ किया।', SV, ['गौरव + अन्वित', 'गौरव + आन्वित', 'गौरवं + इत'], 0, 'गौरव + अन्वित – దీర్ఘ సంధి (अ + अ = आ).')]:
    B.w(1, s, ins, op, k, ex)
B.rc(2, 'हिंदी अपने शाब्दिक अर्थ से भी भारतीय कहलाती है। इसलिए देश के वर्तमान और भविष्य को ध्यान में रखकर भारतीय संविधान ने अनुच्छेद 343(1) के तहत हिंदी को 14 सितंबर 1949 को, राजभाषा के रूप में गौरवान्वित किया। तब से हम हर वर्ष 14 सितंबर को हिंदी दिवस मनाते हैं।',
     [('हिंदी दिवस कब मनाया जाता है?', None), ('भारतीय संविधान ने किसे ध्यान में रखकर हिंदी को राजभाषा के रूप में गौरव दिया?', ['वर्तमान और भविष्य', 'वर्तमान और भूतकाल', 'भूत और भविष्य', 'भविष्य']),
      ('संविधान के किस अनुच्छेद में राजभाषा का प्रस्ताव है?', ['343(1)', '342', '345', '333(1)']), ('हिंदी अपने शाब्दिक अर्थ से क्या कहलाती है?', ['भारतीय', 'हिन्दुस्तान', 'अमेरिकन', 'जापानी'])],
     ['हिंदी दिवस हर वर्ष 14 सितंबर को मनाया जाता है।', 'A) वर्तमान और भविष्य', 'A) 343(1)', 'A) भारतीय'], kind=GD)
q(2, 4, 'अंतर्राष्ट्रीय स्तर पर हिंदी का क्या योगदान है, अपने विचार प्रकट कीजिए।',
  'आज हिंदी विश्व की सबसे अधिक बोली जाने वाली भाषाओं में से एक है। बांग्लादेश, नेपाल, मॉरीशस, फ़िजी, सूरीनाम, त्रिनिदाद, दक्षिण अफ्रीका, अमेरिका, इंग्लैंड, जर्मनी, जापान आदि देशों में हिंदी बोली और पढ़ाई जाती है; कई विदेशी विश्वविद्यालयों में हिंदी विभाग हैं। हर वर्ष 10 जनवरी को विश्व हिंदी दिवस मनाया जाता है; विश्व हिंदी सम्मेलन होते हैं। हिंदी फ़िल्में, गीत, इंटरनेट और व्यापार ने इसे विश्व भर में लोकप्रिय बनाया है। हिंदी जानने वालों को अनुवादक, शिक्षक, पत्रकार, पर्यटन, व्यापार आदि में रोज़गार के अवसर मिलते हैं। इस तरह हिंदी भारतीय संस्कृति को विश्व से जोड़ने वाली कड़ी है।')
ITEMS += B.items
